// Minimal stand-in for the npm package: installs Reflect.metadata/getMetadata/decorate.
const store = new Map();
Reflect.metadata = (key, value) => (target, prop) => {
  store.set(`${key}:${String(prop)}`, value);
};
Reflect.getMetadata = (key, target, prop) => store.get(`${key}:${String(prop)}`);
Reflect.decorate = (decorators, target, prop, desc) => {
  let result = desc;
  for (let i = decorators.length - 1; i >= 0; i--) {
    result = decorators[i](target, prop, result) || result;
  }
  return result;
};
